// One interface, two backends. The choice is made per call, from a live probe.
interface ThreadSummarizer { suspend fun summarize(text: String): String }

class OnDevice(context: Context) : ThreadSummarizer {
  private val client = Summarization.getClient(
    SummarizerOptions.builder(context)
      .setInputType(InputType.ARTICLE)
      .setOutputType(OutputType.THREE_BULLETS)
      .setLanguage(Language.ENGLISH)
      .build()
  )

  // AICore ships on a short device list: a missing model is normal, not an error.
  suspend fun status(): Int = client.checkFeatureStatus().await()

  override suspend fun summarize(text: String): String =
    client.runInference(SummarizationRequest.builder(text).build()).await().summary
}

class Server(private val api: AssistantApi) : ThreadSummarizer {
  override suspend fun summarize(text: String) = api.summarize(SummarizeBody(text)).text
}

class Summaries(private val local: OnDevice, private val remote: Server) {
  suspend fun of(text: String): String {
    // The small model has a small context — length is part of the routing decision.
    val usable = local.status() == FeatureStatus.AVAILABLE && text.length < 4_000
    if (!usable) return remote.summarize(text)
    return runCatching { local.summarize(text) }.getOrElse { remote.summarize(text) }
  }
}

