@Serializable
data class SummarizeRequest(val threadId: String, val tone: Tone, val locale: String)

fun stream(req: SummarizeRequest, turnId: String): Flow<Chunk> = flow {
  http.preparePost("$BASE/v1/threads/summary") {
    header(HttpHeaders.Authorization, "Bearer ${session.accessToken()}") // your user, not the vendor
    header("X-Turn-Id", turnId)                  // one generation, retried safely
    setBody(req)
  }.execute { response ->
    if (response.status == HttpStatusCode.TooManyRequests) {
      emit(Chunk.Quota(response.headers["Retry-After"]?.toIntOrNull() ?: 60))
      return@execute
    }
    val channel = response.bodyAsChannel()
    while (!channel.isClosedForRead) emit(Chunk.Text(channel.readUTF8Line() ?: break))
  }
}
