// Deltas arrive far faster than a frame. Coalesce once, at the boundary.
val answer: Flow<String> = flow {
  val buf = StringBuilder()
  api.streamAnswer(prompt).collect { delta -> buf.append(delta); emit(buf.toString()) }
}
  .sample(48.milliseconds)        // ~20 flushes/s instead of one per token
  .flowOn(Dispatchers.Default)    // string building and Markdown parsing off the main thread

@Composable
fun Thread(messages: List<Message>, state: LazyListState) {
  LazyColumn(state = state) {
    items(messages, key = { it.id }) { m ->
      // ONE item for the whole streaming answer, not one item per token
      MarkdownText(m.text, modifier = Modifier.fillMaxWidth())
    }
  }

  val following by remember {
    derivedStateOf {
      val last = state.layoutInfo.visibleItemsInfo.lastOrNull()
      last != null &&
        last.index == state.layoutInfo.totalItemsCount - 1 &&
        last.offset + last.size <= state.layoutInfo.viewportEndOffset + 48
    }
  }
  // Follow the tail only if the user has not scrolled away from it.
  LaunchedEffect(messages.lastOrNull()?.text) {
    if (following) state.scrollToItem(messages.lastIndex)
  }
}

class AnswerViewModel(private val repo: AnswerRepo) : ViewModel() {
  private var job: Job? = null

  fun ask(turnId: String, prompt: String) {
    job?.cancel()                      // a new question kills the old stream, and its cost
    job = viewModelScope.launch {      // dies with the screen, not with the process
      val partial = StringBuilder()
      repo.stream(turnId, prompt)
        .onEach { partial.append(it); render(partial) }
        .onCompletion { cause ->
          // A cancelled coroutine cannot suspend: without NonCancellable this save never runs.
          withContext(NonCancellable) {
            repo.saveTurn(turnId, partial.toString(), done = cause == null)
          }
        }
        .collect()
    }
  }

  fun stop() {
    job?.cancel()                      // closes the socket; the proxy aborts upstream on that
  }
}

