// The streaming mirror: every field nullable, because every field may not exist yet.
@Serializable data class RecipeDraft(
  val title: String? = null, val minutes: Int? = null, val steps: List<String>? = null,
)

private val lenient = Json { ignoreUnknownKeys = true; isLenient = true }

// Cut back to the last completed member, then close whatever is still open.
private fun repair(prefix: String): String {
  var inString = false; var escaped = false; var cut = 0; var cutDepth = 0
  val open = ArrayDeque<Char>()
  prefix.forEachIndexed { i, c ->
    when {
      escaped -> escaped = false
      inString && c == '\\' -> escaped = true
      c == '"' -> inString = !inString
      inString -> {}
      c == '{' || c == '[' -> open.addLast(if (c == '{') '}' else ']')
      c == '}' || c == ']' -> { open.removeLastOrNull(); cut = i + 1; cutDepth = open.size }
      c == ',' -> { cut = i; cutDepth = open.size }   // everything before it is finished
    }
  }
  // The half-written value at the tail is dropped, not guessed.
  return prefix.take(cut).trimEnd(',') + open.take(cutDepth).reversed().joinToString("")
}

fun Flow<String>.drafts(): Flow<RecipeDraft> =
  runningFold(StringBuilder()) { acc, delta -> acc.append(delta) }
    .mapNotNull { runCatching { lenient.decodeFromString<RecipeDraft>(repair(it.toString())) }.getOrNull() }

@Entity
data class TurnEntity(
  @PrimaryKey val id: String,        // minted on the client, reused by every retry
  val conversationId: String,
  val role: String,                  // "user" | "assistant"
  val text: String,
  val status: String,                // pending | streaming | complete | failed
  val generationId: String? = null,  // what the server calls this answer
  val createdAt: Long,
)

suspend fun resume(conversationId: String) {
  val last = dao.lastTurn(conversationId) ?: return
  if (last.role == "user" || last.status == "complete") return
  val id = last.generationId ?: return dao.update(last.copy(status = "failed"))
  when (val state = api.generation(id)) {
    // The socket died, the generation did not: fetch it, do not pay for it twice.
    is Done -> dao.update(last.copy(text = state.text, status = "complete"))
    is Running -> collectInto(last.id, api.attach(id))
    is Unknown -> dao.update(last.copy(status = "failed"))   // keep the partial text, offer retry
  }
}

// The context you send back up: a truncated turn must never look finished.
fun window(turns: List<TurnEntity>): List<Message> = turns
  .filter { it.status == "complete" }
  .takeLast(20)
  .map { Message(it.role, it.text) }

// TTFT is a different metric from total duration. Time the first chunk, not the last.
suspend fun ask(prompt: String, sink: (String) -> Unit) {
  val started = SystemClock.elapsedRealtime()
  var firstAt: Long? = null
  var tokens = 0
  try {
    api.stream(prompt).collect { chunk ->
      if (firstAt == null) {
        firstAt = SystemClock.elapsedRealtime()
        metrics.timing("assistant.ttft_ms", firstAt!! - started)   // the number the user feels
      }
      tokens += chunk.tokens
      sink(chunk.text)
    }
    val total = SystemClock.elapsedRealtime() - started
    metrics.timing("assistant.total_ms", total)
    metrics.gauge("assistant.tokens_per_s", tokens * 1000.0 / total)
  } catch (cancelled: CancellationException) {
    // Cancelled before the first token means "too slow", not "changed my mind".
    if (firstAt == null) metrics.count("assistant.abandoned_before_first_token")
    throw cancelled
  }
}

