// Play Asset Delivery: the model is an on-demand asset pack, not part of the APK.
class ModelStore(private val packs: AssetPackManager, private val activity: Activity) {

  fun localPath(): String? = packs.getPackLocation(PACK)?.assetsPath()   // null = not here yet

  fun ensure(onReady: (String) -> Unit) {
    localPath()?.let { return onReady(it) }
    packs.registerListener { state ->
      when (state.status()) {
        AssetPackStatus.REQUIRES_USER_CONFIRMATION ->
          packs.showCellularDataConfirmation(activity)   // 1.2 GB on cellular is the user's call
        AssetPackStatus.COMPLETED -> localPath()?.let(onReady)
        AssetPackStatus.FAILED -> Log.w(TAG, "model pack failed: ${state.errorCode()}")
      }
    }
    packs.fetch(listOf(PACK))
  }

  fun evict() {
    packs.removePack(PACK)      // sign-out, or the feature switched off
  }

  private companion object { const val PACK = "llm_v7" }   // versioned with its reader
}

// The feature never waits for the download: it runs on the server until the weights are local.
class Assistant(private val store: ModelStore, private val remote: RemoteAssistant) {
  suspend fun ask(text: String): String {
    // The path can vanish between two calls — the OS reclaims packs. Treat it as a cache.
    val path = store.localPath() ?: return remote.ask(text)
    return runCatching { LocalEngine(path).run(text) }.getOrElse { remote.ask(text) }
  }
}
